#!/usr/bin/env node
// Thin wrapper over the shared root scripts/checkFileLength.mjs (2026-08-13, G4 — this file and
// server's/tools' equivalents used to be ~95%-duplicated copies; merged into one script that a rule
// change only needs to land once). client-specific bits live entirely in the flags below:
// generated network-contract files (openapi-typescript / ts-proto output, regenerated by
// `npm run proto:gen`/`rest:gen`, never hand-edited) and the i18n locale data files (translation
// key/value tables, not code) are excluded from the scan.
//
// Usage: node scripts/checkFileLength.mjs   (run with cwd = client/).
import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SHARED = join(HERE, '..', '..', 'scripts', 'checkFileLength.mjs');

const result = spawnSync(process.execPath, [
  SHARED,
  '--root=src',
  '--baseline=scripts/file-length-baseline.json',
  // Paths here are relative to --root (src/), NOT to client/ — do not repeat the `src/` prefix.
  '--exclude-file=net/openapi.ts,net/openapi-world.ts,net/openapi-social.ts,i18n/locales/zh.ts,i18n/locales/en.ts,i18n/locales/de.ts',
  '--exclude-prefix=net/proto/',
], { stdio: 'inherit' });

process.exit(result.status ?? 1);
